/**
 * The documentation site — a renderer over `content/`, not a second copy of it.
 *
 * Everything under `src/content/docs/` is generated by `scripts/sync-docs.mjs` and
 * git-ignored; the `docsSource()` integration below runs it before every `dev`,
 * `build` and `preview`, and re-projects `content/` while the dev server is up.
 * Read that script's header for what the projection does and why it exists at all.
 *
 * Static output, deliberately: `output` is left at Astro's default, so `pnpm build`
 * writes plain files to `dist/` and any static host serves them. Nothing on this
 * site needs a server — see `../amplify.yml`.
 */

import starlight from "@astrojs/starlight";
import { defineConfig } from "astro/config";

import docsSource from "./integrations/docs-source.mjs";
import remarkMermaid from "./integrations/remark-mermaid.mjs";
import { sidebar } from "./src/sidebar.mjs";

export default defineConfig({
  // No `site`, and that is a decision rather than an omission: this repository does
  // not own the domain yet (Amplify assigns one), and a wrong canonical URL is
  // worse than none. Set it here the day the domain is real — it is what turns on
  // canonical links and a sitemap.
  integrations: [
    docsSource(),
    starlight({
      title: "VisionSet Documentation",
      description:
        "Local-first, SDK-first computer-vision dataset tooling by Robomous — ingest, annotate, version, split and export, with every surface a thin client of one SDK.",
      favicon: "/favicon.ico",
      // The Robomous wordmark, one per theme — the same banner and the same accent
      // the other Robomous documentation sites carry, so they read as one family.
      // A PNG for dark rather than a second SVG because that is the asset the
      // brand set ships; Starlight swaps them with its own light/dark classes.
      logo: {
        light: "./src/assets/robomous-logo-banner.svg",
        dark: "./src/assets/robomous-logo-banner-white.png",
        alt: "Robomous",
      },
      // Every page carries its own `editUrl` in frontmatter, written by the
      // projection. A global `baseUrl` cannot work here: `content/README.md` is
      // served as `index.md`, so a prefix would point at a file that does not exist.
      editLink: {},
      social: [
        { icon: "github", label: "GitHub", href: "https://github.com/Robomous/VisionSet" },
      ],
      customCss: ["./src/styles/visionset.css"],
      // A code block gets a title tab naming its language; a terminal block
      // deliberately does not, because Expressive Code already draws those as a
      // terminal window and a "Bash" tab on top of one says the same thing twice.
      // `content/` is overwhelmingly Python and shell, so this is the whole list.
      expressiveCode: {
        defaultProps: {
          overridesByLang: {
            python: { title: "Python" },
            py: { title: "Python" },
          },
        },
      },
      components: {
        // Adds the client half of the mermaid support below. It renders Starlight's
        // own `<Head>` and appends to it, so nothing standard is lost.
        Head: "./src/components/Head.astro",
      },
      sidebar,
      lastUpdated: false,
      // `content/` has one `# H1` per page and the projection lifts it into the
      // frontmatter title, so the deepest heading a page's own outline needs is
      // `###`. Two levels is what the documents actually use.
      tableOfContents: { minHeadingLevel: 2, maxHeadingLevel: 3 },
    }),
  ],
  markdown: {
    remarkPlugins: [remarkMermaid],
  },
});
